local f = assert ( io.open ( file , "rb" ))
local content = f : read ( "*all" )
f : close ()
return content
end
function test_x509 ()
local certasstring = readAll ( "invalid_cert.pem" )
local x = openssl . x509 . read ( certasstring )
print ( x : check_host ( "github.com" ))
end
